import { apiUrl } from "./api";
/* Neural voice generated by the backend (/api/tts): mp3 audio + word timings.
   Falls back to the browser's speechSynthesis (speech.ts) when unavailable. */

export type SpeechWord = { text: string; start: number; duration: number }; // seconds
export type Speech = { audio: string; format: string; voice: string; words: SpeechWord[] };
export type VoiceInfo = { name: string; locale: string; gender: string };

const VOICE_KEY = "oski.ttsVoice";
const RATE_KEY = "oski.ttsRate";
export const DEFAULT_RATE_PCT = 6;

function stored(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function store(key: string, value: string) {
  try {
    localStorage.setItem(key, value);
  } catch {
    /* private mode: preference just isn't remembered */
  }
}

export const getTtsVoice = () => stored(VOICE_KEY) ?? "";
export const setTtsVoice = (name: string) => store(VOICE_KEY, name);
export const getTtsRate = () => {
  const value = Number(stored(RATE_KEY));
  return Number.isFinite(value) && stored(RATE_KEY) !== null ? value : DEFAULT_RATE_PCT;
};
export const setTtsRate = (pct: number) => store(RATE_KEY, String(pct));

const rateString = (pct: number) => `${pct >= 0 ? "+" : ""}${Math.round(pct)}%`;

/** Neural speech for `text`, or null if the server can't produce it. */
export async function fetchSpeech(text: string): Promise<Speech | null> {
  try {
    const response = await fetch(apiUrl("/api/tts"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text, voice: getTtsVoice() || undefined, rate: rateString(getTtsRate()) }),
    });
    return response.ok ? ((await response.json()) as Speech) : null;
  } catch {
    return null;
  }
}

export async function listVoices(): Promise<{ default: string; voices: VoiceInfo[] } | null> {
  try {
    const response = await fetch(apiUrl("/api/tts/voices"));
    return response.ok ? await response.json() : null;
  } catch {
    return null;
  }
}

export function base64ToArrayBuffer(b64: string): ArrayBuffer {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

/** Char index in `text` where each spoken word starts (for karaoke captions). */
export function wordOffsets(text: string, words: SpeechWord[]): number[] {
  const lower = text.toLowerCase();
  let cursor = 0;
  return words.map((w) => {
    const at = lower.indexOf(w.text.toLowerCase(), cursor);
    if (at === -1) return cursor;
    cursor = at + w.text.length;
    return at;
  });
}

/** Plays neural speech with a plain <audio> element (chat mode). */
export function playSpeech(speech: Speech, onWord?: (index: number) => void) {
  const audio = new Audio(`data:audio/mpeg;base64,${speech.audio}`);
  const timers: number[] = [];
  const clear = () => timers.splice(0).forEach((t) => window.clearTimeout(t));
  let resolveDone: () => void = () => {};
  const done = new Promise<void>((resolve) => (resolveDone = resolve));
  const finish = () => {
    clear();
    resolveDone();
  };
  audio.onplay = () => speech.words.forEach((w, i) => timers.push(window.setTimeout(() => onWord?.(i), w.start * 1000)));
  audio.onended = finish;
  audio.onerror = finish;
  // started: false when the browser refuses to play (e.g. no user gesture yet).
  const started = audio.play().then(
    () => true,
    () => {
      finish();
      return false;
    },
  );
  return {
    done,
    started,
    cancel: () => {
      audio.pause();
      finish();
    },
  };
}
